// pubspec.yaml:
//   firebase_messaging: ^14.7.0
//   flutter_local_notifications: ^16.3.0 (for foreground display)

import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter_local_notifications/flutter_local_notifications.dart';

// ────── 1. TOP-LEVEL background handler ──────
// MUST be a top-level function (not a class method).
// Runs in a SEPARATE Dart isolate — no shared state with main isolate.
@pragma('vm:entry-point')
Future<void> onBackgroundMessage(RemoteMessage m) async {
  await Firebase.initializeApp();   // isolate needs its own init
  // update local storage, refresh Hive, ping backend, etc.
  print('bg: ${m.messageId} data=${m.data}');
}

// ────── 2. Main setup ──────
Future<void> initFcm() async {
  final fm = FirebaseMessaging.instance;

  // Permission (iOS + Android 13+)
  await fm.requestPermission(alert: true, badge: true, sound: true);

  // Background handler MUST be registered before runApp
  FirebaseMessaging.onBackgroundMessage(onBackgroundMessage);

  // Foreground presentation on iOS — show banner even when app open
  await fm.setForegroundNotificationPresentationOptions(
      alert: true, badge: true, sound: true);

  // Token — send to your backend + observe rotation
  final token = await fm.getToken();
  await api.registerFcmToken(user.uid, token);
  fm.onTokenRefresh.listen((newToken) => api.registerFcmToken(user.uid, newToken));

  // Foreground: manually display via flutter_local_notifications
  FirebaseMessaging.onMessage.listen((m) {
    _showLocalNotification(m);
  });

  // User TAPPED a notification while app was in background — deep link
  FirebaseMessaging.onMessageOpenedApp.listen((m) {
    _handleDeepLink(m.data['deep_link']);
  });

  // App started FROM a notification tap (from terminated state)
  final initial = await fm.getInitialMessage();
  if (initial != null) _handleDeepLink(initial.data['deep_link']);

  // Topics — mass fan-out (no per-user server logic)
  await fm.subscribeToTopic('promo_india');
  // await fm.unsubscribeFromTopic('promo_india');
}

// ────── 3. Foreground notification display ──────
final _local = FlutterLocalNotificationsPlugin();
void _showLocalNotification(RemoteMessage m) {
  _local.show(
    m.messageId.hashCode,
    m.notification?.title,
    m.notification?.body,
    NotificationDetails(
      android: AndroidNotificationDetails('default', 'Default',
          importance: Importance.high, priority: Priority.high),
      iOS: const DarwinNotificationDetails(),
    ),
    payload: m.data.toString(),
  );
}

// Server (Cloud Functions / Node service)
const admin = require('firebase-admin');
admin.initializeApp();

// ────── Single-device send ──────
await admin.messaging().send({
  token,
  notification: { title: 'New order', body: 'Order #123 shipped' },
  data: { orderId: '123', deep_link: '/orders/123' },
  android: {
    priority: 'high',
    notification: { channelId: 'orders', sound: 'default' }
  },
  apns: {
    payload: { aps: { badge: 1, sound: 'default', 'content-available': 1 } }
  }
});

// ────── Topic ──────
await admin.messaging().send({
  topic: 'promo_india',
  notification: { title: 'Diwali offer', body: '40% off!' }
});

// ────── Condition ──────
await admin.messaging().send({
  condition: "'promo_india' in topics && 'plan_pro' in topics",
  notification: { title: 'Pro-only deal', body: '...' }
});

// ────── Batch (up to 500 tokens per call) ──────
await admin.messaging().sendEachForMulticast({
  tokens: [t1, t2, t3],
  data: { badge: '5' }
});

// ────── OLD legacy server key API is DEPRECATED (June 2024) ──────
// Use HTTP v1 OAuth-signed endpoint only.
